SELECT c.id
FROM customers c
WHERE NOT EXISTS (
  SELECT 1 FROM products p
  WHERE NOT EXISTS (
    SELECT 1 FROM purchases x
    WHERE x.customer_id = c.id AND x.product_key = p.product_key
  )
);

WITH ranked AS (
 SELECT t.*, ROW_NUMBER() OVER (
   PARTITION BY business_key ORDER BY updated_at DESC, id DESC
 ) AS rn FROM incoming t
)
SELECT id, business_key, updated_at
FROM ranked WHERE rn = 1;
